package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LedgerRec struct { // 01 LEDGER-REC, 14 bytes
	BrBranch string // PIC X(2) @0 len=2
	BrAcct string // PIC X(4) @2 len=4
	BrType string // PIC X(1) @6 len=1
	BrAmt decimal.Decimal // PIC 9(5)V99 @7 len=7
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string // PIC X len=1 = "N"
var WsFirstFlag string // PIC X len=1 = "Y"
var WsPrevBranch string // PIC X(2) len=2 = SPACES
var WsPrevAcct string // PIC X(4) len=4 = SPACES
var WsBal decimal.Decimal // PIC S9(7)V99 len=9 = 0
var WsBranchTot decimal.Decimal // PIC S9(9)V99 len=11 = 0
var WsGrandTot decimal.Decimal // PIC S9(9)V99 len=11 = 0
var WsSkipped int64 // PIC 99 len=2 = 0
var WsAmtEd string // PIC ZZ,ZZ9.99 len=9
var WsBalEd string // PIC -Z,ZZZ,ZZ9.99 len=13
var WsTotEd string // PIC -ZZZ,ZZZ,ZZ9.99 len=15

var curRec LedgerRec
var ledgerLines []string
var ledgerPos int

func inputDone() bool { return WsEofFlag == "Y" }
func firstRecord() bool { return WsFirstFlag == "Y" }

func pow10(n int) int64 {
	var r int64 = 1
	for i := 0; i < n; i++ {
		r *= 10
	}
	return r
}

func storeBal(v decimal.Decimal) decimal.Decimal {
	t := v.Truncate(2)
	scaled := t.Shift(2).Truncate(0).IntPart()
	base := pow10(9)
	rem := scaled % base
	return decimal.New(rem, -2)
}

func storeTot(v decimal.Decimal) decimal.Decimal {
	t := v.Truncate(2)
	scaled := t.Shift(2).Truncate(0).IntPart()
	base := pow10(11)
	rem := scaled % base
	return decimal.New(rem, -2)
}

func formatIntPattern(intPart int64, intDigits int, pattern string) string {
	digits := make([]int, intDigits)
	tmp := intPart
	for i := intDigits - 1; i >= 0; i-- {
		digits[i] = int(tmp % 10)
		tmp /= 10
	}
	var sb strings.Builder
	significant := false
	di := 0
	for _, ch := range pattern {
		switch ch {
		case ',':
			if significant {
				sb.WriteByte(',')
			} else {
				sb.WriteByte(' ')
			}
		case 'Z':
			d := digits[di]
			di++
			if significant {
				sb.WriteByte(byte('0' + d))
			} else {
				if d != 0 {
					significant = true
					sb.WriteByte(byte('0' + d))
				} else {
					sb.WriteByte(' ')
				}
			}
		case '9':
			d := digits[di]
			di++
			sb.WriteByte(byte('0' + d))
			significant = true
		default:
			sb.WriteByte(byte(ch))
		}
	}
	return sb.String()
}

func scaledModAbs(v decimal.Decimal, intDigits int) (int64, int64) {
	a := v.Abs().Truncate(2)
	scaled := a.Shift(2).IntPart()
	base := pow10(intDigits + 2)
	m := scaled % base
	if m < 0 {
		m = -m
	}
	ip := m / 100
	fp := m % 100
	return ip, fp
}

func formatAmtEd(v decimal.Decimal) string {
	ip, fp := scaledModAbs(v, 5)
	intStr := formatIntPattern(ip, 5, "ZZ,ZZ9")
	fracStr := fmt.Sprintf("%02d", fp)
	return intStr + "." + fracStr
}

func formatBalEd(v decimal.Decimal) string {
	sign := byte(' ')
	if v.Sign() < 0 {
		sign = byte('-')
	}
	ip, fp := scaledModAbs(v, 7)
	intStr := formatIntPattern(ip, 7, "Z,ZZZ,ZZ9")
	fracStr := fmt.Sprintf("%02d", fp)
	return string([]byte{sign}) + intStr + "." + fracStr
}

func formatTotEd(v decimal.Decimal) string {
	sign := byte(' ')
	if v.Sign() < 0 {
		sign = byte('-')
	}
	ip, fp := scaledModAbs(v, 9)
	intStr := formatIntPattern(ip, 9, "ZZZ,ZZZ,ZZ9")
	fracStr := fmt.Sprintf("%02d", fp)
	return string([]byte{sign}) + intStr + "." + fracStr
}

func display(parts ...string) {
	var sb strings.Builder
	for _, p := range parts {
		sb.WriteString(p)
	}
	sb.WriteString("\n")
	os.Stdout.WriteString(sb.String())
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func openLedger() {
	WsEofFlag = "N"
	WsFirstFlag = "Y"
	WsPrevBranch = "  "
	WsPrevAcct = "    "
	WsBal = decimal.NewFromInt(0)
	WsBranchTot = decimal.NewFromInt(0)
	WsGrandTot = decimal.NewFromInt(0)
	WsSkipped = 0
	ledgerLines = nil
	ledgerPos = 0
	f, err := os.Open("input.dat")
	if err != nil {
		return
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	// allow long lines
	const maxCap = 1024 * 1024
	buf := make([]byte, 0, 64*1024)
	sc.Buffer(buf, maxCap)
	for sc.Scan() {
		line := sc.Text()
		// Scanner strips \r\n and \n; remove stray \r if any
		if len(line) > 0 && line[len(line)-1] == '\r' {
			line = line[:len(line)-1]
		}
		ledgerLines = append(ledgerLines, line)
	}
}

func parseLine(line string) LedgerRec {
	// pad with spaces to 14 bytes on right, truncate if longer
	// operate on bytes
	b := []byte(line)
	if len(b) < 14 {
		nb := make([]byte, 14)
		copy(nb, b)
		for i := len(b); i < 14; i++ {
			nb[i] = ' '
		}
		b = nb
	} else if len(b) > 14 {
		b = b[:14]
	}
	br := string(b[0:2])
	ac := string(b[2:6])
	ty := string(b[6:7])
	amtBytes := b[7:14]
	var n int64 = 0
	for _, c := range amtBytes {
		var d int64
		if c >= '0' && c <= '9' {
			d = int64(c - '0')
		} else {
			d = 0
		}
		n = n*10 + d
	}
	return LedgerRec{
		BrBranch: br,
		BrAcct:   ac,
		BrType:   ty,
		BrAmt:    decimal.New(n, -2),
	}
}

func READPARA() {
	if ledgerPos >= len(ledgerLines) {
		WsEofFlag = "Y"
		return
	}
	curRec = parseLine(ledgerLines[ledgerPos])
	ledgerPos++
}

func PROCESSPARA() {
	if firstRecord() {
		WsPrevBranch = curRec.BrBranch
		WsPrevAcct = curRec.BrAcct
		WsFirstFlag = "N"
	} else {
		if curRec.BrBranch != WsPrevBranch {
			ACCTBREAKPARA()
			BRANCHBREAKPARA()
			WsPrevBranch = curRec.BrBranch
			WsPrevAcct = curRec.BrAcct
		} else {
			if curRec.BrAcct != WsPrevAcct {
				ACCTBREAKPARA()
				WsPrevAcct = curRec.BrAcct
			}
		}
	}
	POSTPARA()
	READPARA()
}

func POSTPARA() {
	WsAmtEd = formatAmtEd(curRec.BrAmt)
	switch curRec.BrType {
	case "D":
		WsBal = storeBal(WsBal.Add(curRec.BrAmt))
		display(curRec.BrAcct, " D ", WsAmtEd)
	case "C":
		WsBal = storeBal(WsBal.Sub(curRec.BrAmt))
		display(curRec.BrAcct, " C ", WsAmtEd)
	default:
		WsSkipped = (WsSkipped + 1) % 100
		display(curRec.BrAcct, " ? SKIPPED")
	}
}

func ACCTBREAKPARA() {
	WsBalEd = formatBalEd(WsBal)
	display("  ACCOUNT ", WsPrevAcct, " BALANCE:", WsBalEd)
	WsBranchTot = storeTot(WsBranchTot.Add(WsBal))
	WsBal = decimal.NewFromInt(0)
}

func BRANCHBREAKPARA() {
	WsTotEd = formatTotEd(WsBranchTot)
	display(" BRANCH ", WsPrevBranch, " TOTAL:", WsTotEd)
	WsGrandTot = storeTot(WsGrandTot.Add(WsBranchTot))
	WsBranchTot = decimal.NewFromInt(0)
}

func GRANDPARA() {
	WsTotEd = formatTotEd(WsGrandTot)
	display("GRAND TOTAL:", WsTotEd)
	sk := fmt.Sprintf("%02d", WsSkipped)
	display("SKIPPED: ", sk)
}

func main() {
	openLedger()
	READPARA()
	for !inputDone() {
		PROCESSPARA()
	}
	if !firstRecord() {
		ACCTBREAKPARA()
		BRANCHBREAKPARA()
	}
	GRANDPARA()
}
